	num = size / sizeof(u64);
	if (num > 0) {
		u64 batch = min_t(u64, num, fc->max_pages);

		nodeids = kmalloc(batch * sizeof(u64), GFP_KERNEL);
		if (!nodeids) {
			err = -ENOMEM;
			goto err;
		}

		for (size_t i = 0; i < num; i += batch) {
			size_t n = min_t(size_t, num - i, batch);

